import abc
import re

import six
from moler.cmd.commandtextualgeneric import CommandTextualGeneric
from moler.exceptions import CommandFailure, ParsingDone


@six.add_metaclass(abc.ABCMeta)
class GenericIphy(CommandTextualGeneric):
    """Genericiphy command class."""

    def __init__(self, connection, prompt=None, newline_chars=None, runner=None):
        """
        Genericiphy command.

        :param connection: moler connection to device, terminal when command is executed.
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(GenericIphy, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_error(line)
            except ParsingDone:
                pass  # line has been fully parsed by one of above parse-methods
        return super(GenericIphy, self).on_new_line(line, is_full_line)

    # Error: /opt/IRFHeadExe/IRFHeadExe should be started from AppDef.txt
    _re_error = re.compile(r"^Error|ERR")

    def _parse_error(self, line):
        if self._regex_helper.search_compiled(GenericIphy._re_error, line):
            self.set_exception(CommandFailure(self, f"Error: {line}"))
            raise ParsingDone
